body.query:
query OccurrenceSearch(
  $from: Int
  $size: Int
  $predicate: Predicate
  $q: String
  $language: String
  $sortBy: OccurrenceSortBy
  $sortOrder: SortOrder
  $checklistKey: ID
) {
  occurrenceSearch(q: $q, predicate: $predicate) {
    documents(from: $from, size: $size, sortBy: $sortBy, sortOrder: $sortOrder) {
      from
      size
      total
      results {
        key
        taxonKey
        verbatimScientificName
        classification(checklistKey: $checklistKey) {
          usage {
            rank
            name
            key
          }
          taxonMatch {
            usage {
              name
              key
              canonicalName
              formattedName
            }
          }
          meta {
            mainIndex {
              datasetTitle
            }
          }
          vernacularNames(lang: $language, maxLimit: 1) {
            name
            reference {
              citation
            }
          }
          hasTaxonIssues
        }
        primaryImage {
          thumbor(width: 80)
        }
        eventDate
        year
        coordinates
        formattedCoordinates
        country
        countryCode
        basisOfRecord
        datasetTitle
        datasetKey
        publishingOrgKey
        publisherTitle
        catalogNumber
        recordedBy
        identifiedBy
        fieldNumber
        occurrenceRemarks(cap: 150)
        sex
        lifeStage
        recordNumber
        individualCount
        organismQuantity
        organismQuantityType
        typeStatus
        occurrenceStatus
        preparations
        institutionCode
        institutionKey
        institution {
          code
          name
        }
        collectionCode
        collectionKey
        collection {
          code
          name
        }
        organismID
        elevation
        depth
        locality
        higherGeography
        stateProvince
        establishmentMeans
        iucnRedListCategory
        stillImageCount
        movingImageCount
        soundCount
        issues(types: ["WARNING", "ERROR"])
        volatile {
          features {
            isSequenced
            isTreament
            isClustered
            isSamplingEvent
          }
        }
      }
    }
  }
}
